 useEffect(()=>{if(!supabase||!user){setSettingsOwner("");return;}let alive=true;supabase.from("tg_profiles").select("privacy_settings").eq("id",user.id).maybeSingle().then(({data,error})=>{if(!alive)return;if(error){console.error("Не удалось загрузить настройки конфиденциальности",error);setSettingsSyncStatus("Не удалось загрузить настройки с сервера");return;}const saved=data?.privacy_settings;if(saved&&typeof saved==="object"&&!Array.isArray(saved))setSettingsPrefs(p=>({...p,...saved}));setSettingsOwner(user.id);});return()=>{alive=false;};},[user]);
 useEffect(()=>{if(privacyDialog==="blacklist")void loadBlockedUsers();},[privacyDialog,user]);
 useEffect(()=>{if(privacyDialog==="cloudPassword")void loadMfaFactors();},[privacyDialog,user]);
 useEffect(()=>{let alive=true;if(!supabase||!user){setMfaLoginRequired(false);setMfaCheckedUser("");return;}if(mfaCheckedUser===user.id)return;setMfaCheckedUser(user.id);(async()=>{const [{data:factors,error:fError},{data:assurance,error:aError}]=await Promise.all([supabase.auth.mfa.listFactors(),supabase.auth.mfa.getAuthenticatorAssuranceLevel()]);if(!alive)return;if(fError||aError){setMfaLoginError("Не удалось проверить двухэтапную защиту.");return;}const verified=factors?.totp?.find((factor:any)=>factor.status==="verified");if(verified&&assurance?.currentLevel!=="aal2"){const {data:challenge,error}=await supabase.auth.mfa.challenge({factorId:verified.id});if(!alive)return;if(error||!challenge){setMfaLoginError("Не удалось начать двухэтапную проверку.");return;}setMfaLoginFactorId(verified.id);setMfaLoginChallengeId(challenge.id);setMfaLoginRequired(true);}})();return()=>{alive=false;};},[user,mfaCheckedUser]);
 async function verifyLoginMfa(){if(!supabase||!mfaLoginFactorId||!mfaLoginChallengeId||mfaLoginCode.length!==6)return;setMfaLoginBusy(true);setMfaLoginError("");const {error}=await supabase.auth.mfa.verify({factorId:mfaLoginFactorId,challengeId:mfaLoginChallengeId,code:mfaLoginCode});setMfaLoginBusy(false);if(error){setMfaLoginError("Неверный код. Проверь его и попробуй снова.");return;}setMfaLoginRequired(false);setMfaLoginCode("");setMfaLoginChallengeId("");}
 useEffect(()=>{if(!supabase||!user||settingsOwner!==user.id)return;let alive=true;setSettingsSyncStatus("Сохранение…");supabase.from("tg_profiles").update({privacy_settings:settingsPrefs}).eq("id",user.id).then(({error})=>{if(!alive)return;setSettingsSyncStatus(error?"Ошибка синхронизации":"Синхронизировано");if(error)console.error("Не удалось сохранить настройки конфиденциальности",error);});return()=>{alive=false;};},[settingsPrefs,settingsOwner,user]);
 useEffect(()=>{try{localStorage.setItem("topgram-settings-v1",JSON.stringify(settingsPrefs));const root=document.documentElement;root.dataset.animations=settingsPrefs.animations?"on":"off";const apply=()=>{root.dataset.theme=settingsPrefs.theme==="system"?(window.matchMedia("(prefers-color-scheme: light)").matches?"light":"dark"):settingsPrefs.theme;};apply();if(settingsPrefs.theme!=="system")return;const media=window.matchMedia("(prefers-color-scheme: light)");media.addEventListener("change",apply);return()=>media.removeEventListener("change",apply);}catch{}},[settingsPrefs]);
