 function updatePreference<K extends keyof typeof settingsPrefs>(key:K,value:(typeof settingsPrefs)[K]){setSettingsPrefs(p=>{const next={...p,[key]:value};try{localStorage.setItem("topgram-settings-prefs-"+(user?.id??"local"),JSON.stringify(next));}catch{}return next;});}
 useEffect(()=>{try{const saved=localStorage.getItem("topgram-settings-prefs-"+(user?.id??"local"));if(saved){const parsed=JSON.parse(saved);if(parsed&&typeof parsed==="object")setSettingsPrefs({...defaultSettingsPrefs,...parsed});else setSettingsPrefs({...defaultSettingsPrefs});}else setSettingsPrefs({...defaultSettingsPrefs});}catch{setSettingsPrefs({...defaultSettingsPrefs});}},[user?.id]);
 async function loadGiftMarket(){if(!supabase||!user)return;setMarketBusy(true);setMarketError("");const [catalog,releases,drops,ledger]=await Promise.all([supabase.from("tg_gift_catalog").select("id,code,title,description,image_url,stars_price,upgrade_price,limited_quantity").eq("is_active",true).order("created_at",{ascending:false}),supabase.from("tg_gift_market_drops").select("id,gift_id,quantity_remaining,quantity_total").eq("is_active",true).gt("quantity_remaining",0),supabase.from("tg_gift_drops").select("id,quantity,note,created_at,is_upgraded,unique_number,attributes,upgraded_at,gift:tg_gift_catalog(title,description,image_url,stars_price,upgrade_price)").eq("user_id",user.id).order("created_at",{ascending:false}),supabase.from("tg_star_ledger").select("id,amount,reason,created_at").eq("user_id",user.id).order("created_at",{ascending:false}).limit(30)]);setMarketBusy(false);if(catalog.error||releases.error||drops.error||ledger.error){setMarketError("Не удалось загрузить магазин. Попробуй обновить раздел.");return;}const remaining=(releases.data??[]).reduce((acc:any,r:any)=>{acc[r.gift_id]=(acc[r.gift_id]??0)+Number(r.quantity_remaining);return acc;},{});setGiftMarket((catalog.data??[]).filter((g:any)=>Number(remaining[g.id]??0)>0).map((g:any)=>({...g,market_remaining:remaining[g.id]})));setMyGiftDrops(drops.data??[]);setStarHistory(ledger.data??[]);}
 async function buyMarketGift(gift:any){if(!supabase||!gift?.id||buyingGiftId)return;setBuyingGiftId(gift.id);setMarketError("");setMarketMessage("");try{const {data,error}=await supabase.rpc("tg_buy_gift",{p_gift_id:gift.id});if(error)throw error;const result=data as any;if(result?.stars_balance!==undefined)setStarsBalance(Number(result.stars_balance));setMarketMessage("Подарок «"+gift.title+"» добавлен в твою коллекцию.");await loadGiftMarket();}catch(error){setMarketError(error instanceof Error?error.message:"Не удалось купить подарок.");}finally{setBuyingGiftId("");}}
 async function upgradeOwnedGift(drop:any){if(!supabase||!drop?.id||buyingGiftId)return;setBuyingGiftId(drop.id);setMarketError("");setMarketMessage("");try{const {data,error}=await supabase.rpc("tg_upgrade_gift",{p_drop_id:drop.id});if(error)throw error;const result=data as any;if(result?.stars_balance!==undefined)setStarsBalance(Number(result.stars_balance));setMarketMessage("Подарок улучшен! Экземпляр №"+result.unique_number+".");await loadGiftMarket();}catch(error){setMarketError(error instanceof Error?error.message:"Не удалось улучшить подарок.");}finally{setBuyingGiftId("");}}
