 async function verifyMfaEnrollment(){if(!supabase||!mfaFactorId||!mfaCode.trim())return;setMfaBusy(true);const {data:challenge,error:challengeError}=await supabase.auth.mfa.challenge({factorId:mfaFactorId});if(challengeError||!challenge){setMfaBusy(false);setMfaMessage("Не удалось создать проверку: "+(challengeError?.message??"ошибка"));return;}const {error}=await supabase.auth.mfa.verify({factorId:mfaFactorId,challengeId:challenge.id,code:mfaCode.trim()});setMfaBusy(false);if(error){setMfaMessage("Код не подошёл: "+error.message);return;}setMfaQr("");setMfaSecret("");setMfaCode("");setMfaMessage("Двухэтапная защита включена.");await loadMfaFactors();}
