 function openSettingsSection(section:typeof settingsSection){setSettingsSection(section);setMobileTab("settings");setMobileChat(false);}

 useEffect(()=>{if(!supabase||!user||!activeId||!settingsPrefs.readReceipts)return;const unread=messages.filter(m=>m.chatId===activeId&&!m.mine&&!m.read).map(m=>({message_id:m.id,reader_id:user.id}));if(!unread.length)return;let alive=true;supabase.from("tg_message_reads").upsert(unread,{onConflict:"message_id,reader_id",ignoreDuplicates:true}).then(({error})=>{if(!alive)return;if(error){console.error("Не удалось отметить сообщения прочитанными",error);return;}setMessages(prev=>prev.map(m=>m.chatId===activeId&&!m.mine?{...m,read:true}:m));});return()=>{alive=false;};},[activeId,messages,user,settingsPrefs.readReceipts]);
 useEffect(()=>{const client=supabase;if(!client||!user)return;const channel=client.channel("topgram-live-"+user.id).on("postgres_changes",{event:"INSERT",schema:"public",table:"tg_messages"},payload=>{const row=payload.new as {id:string;conversation_id:string;sender_id:string;body:string;created_at:string;attachment_path?:string|null;attachment_name?:string|null;attachment_type?:string|null;attachment_size?:number|null};setMessages(prev=>prev.some(m=>m.id===row.id)?prev:[...prev,{id:row.id,chatId:row.conversation_id,text:row.body,mine:row.sender_id===user.id,time:timeLabel(row.created_at),attachmentPath:row.attachment_path??undefined,attachmentName:row.attachment_name??undefined,attachmentType:row.attachment_type??undefined,attachmentSize:row.attachment_size??undefined}]);setChats(prev=>prev.map(c=>c.id===row.conversation_id?{...c,preview:row.attachment_name?"📎 "+row.attachment_name:row.body,time:timeLabel(row.created_at)}:c));}).on("postgres_changes",{event:"UPDATE",schema:"public",table:"tg_messages"},payload=>{const row=payload.new as {id:string;conversation_id:string;body:string};setMessages(prev=>prev.map(m=>m.id===row.id?{...m,text:row.body}:m));setChats(prev=>prev.map(c=>c.id===row.conversation_id?{...c,preview:row.body}:c));}).on("postgres_changes",{event:"DELETE",schema:"public",table:"tg_messages"},payload=>{const row=payload.old as {id:string};setMessages(prev=>prev.filter(m=>m.id!==row.id));}).on("postgres_changes",{event:"INSERT",schema:"public",table:"tg_message_reads"},payload=>{const row=payload.new as {message_id:string;reader_id:string};if(row.reader_id!==user.id)setMessages(prev=>prev.map(m=>m.id===row.message_id?{...m,read:true}:m));}).subscribe();return()=>{void client.removeChannel(channel);};},[user]);

 useEffect(()=>{const client=supabase;if(!client||!user||settingsOwner!==user.id)return;const canShow=settingsPrefs.lastSeen&&settingsPrefs.lastSeenVisibility==="Все";const channel=client.channel("topgram-presence",{config:{presence:{key:user.id}}});const syncOnline=()=>{const onlineIds=new Set(Object.values(channel.presenceState()).flat().map((entry:any)=>entry.user_id).filter((id:any)=>typeof id==="string"));setChats(prev=>prev.map(chat=>({...chat,online:Boolean(canShow&&chat.peerId&&onlineIds.has(chat.peerId))})));};channel.on("presence",{event:"sync"},syncOnline).on("presence",{event:"join"},syncOnline).on("presence",{event:"leave"},syncOnline).subscribe(async status=>{if(status==="SUBSCRIBED"&&canShow){await channel.track({user_id:user.id,online:true});syncOnline();}});return()=>{void client.removeChannel(channel);};},[user,settingsOwner,settingsPrefs.lastSeen,settingsPrefs.lastSeenVisibility]);
 async function toggleVoiceRecording(){if(voiceRecording){recorderRef.current?.stop();setVoiceRecording(false);return;}if(!active||!navigator.mediaDevices?.getUserMedia||typeof MediaRecorder==="undefined"){setActionError("Запись голоса не поддерживается этим браузером.");return;}try{const stream=await navigator.mediaDevices.getUserMedia({audio:true});const recorder=new MediaRecorder(stream);recorderRef.current=recorder;recordingChunksRef.current=[];recorder.ondataavailable=event=>{if(event.data.size)recordingChunksRef.current.push(event.data);};recorder.onstop=()=>{stream.getTracks().forEach(track=>track.stop());const blob=new Blob(recordingChunksRef.current,{type:recorder.mimeType||"audio/webm"});if(blob.size){const file=new File([blob],"voice-message.webm",{type:blob.type||"audio/webm"});void uploadAttachment(file);}recorderRef.current=null;};recorder.start();setVoiceRecording(true);setActionError("");}catch(error){setActionError(error instanceof Error&&error.name==="NotAllowedError"?"Разреши доступ к микрофону, чтобы записать голосовое сообщение.":"Не удалось начать запись голосового сообщения.");}}
 async function send(e:FormEvent){e.preventDefault();const text=draft.trim();if(!text||!active||messageSendBusy)return;if(text.length>10000){setActionError("Сообщение слишком длинное (максимум 10 000 символов).");return;}if(!supabase||!user){setActionError("Войди в аккаунт, чтобы отправлять сообщения.");return;}setMessageSendBusy(true);setActionError("");try{const {data,error}=await supabase.from("tg_messages").insert({conversation_id:active.id,sender_id:user.id,body:text}).select("id,created_at").single();if(error)throw error;if(data){setDraft("");const item:Message={id:data.id,chatId:active.id,text,mine:true,time:timeLabel(data.created_at)};setMessages(prev=>prev.some(m=>m.id===item.id)?prev:[...prev,item]);setChats(prev=>prev.map(c=>c.id===active.id?{...c,preview:text,time:item.time}:c));try{await invokeBotApiAction({method:"ingest",conversation_id:active.id,message_id:data.id});}catch(error){console.error("Bot update delivery failed",error);}if(active.handle.toLowerCase()==="@botfather"){try{await invokeBotFatherAction("handle",{conversation_id:active.id,text});await loadWorkspace(user);}catch(error){setActionError(error instanceof Error?error.message:"BotFather не смог обработать команду.");}}}}catch(error){setActionError("Не удалось отправить сообщение: "+(error instanceof Error?error.message:"ошибка"));}finally{setMessageSendBusy(false);}}
 async function uploadAttachment(file?:File){if(!file||!active||!supabase||!user)return;if(file.size>20*1024*1024){setActionError("Файл больше 20 МБ. Выбери файл поменьше.");return;}const allowed=["image/jpeg","image/png","image/webp","image/gif","video/mp4","video/webm","audio/mpeg","audio/mp4","audio/ogg","audio/webm","application/pdf","text/plain","application/zip"];if(!allowed.includes(file.type)){setActionError("Этот формат пока не поддерживается.");return;}setUploadBusy(true);setActionError("");try{const safeName=file.name.replace(/[^a-zA-Z0-9._-]/g,"_").slice(-100)||"file";const path=user.id+"/"+active.id+"/"+crypto.randomUUID()+"_"+safeName;const {error:uploadError}=await supabase.storage.from("topgram-chat-media").upload(path,file,{contentType:file.type,upsert:false});if(uploadError)throw uploadError;const {data,error}=await supabase.from("tg_messages").insert({conversation_id:active.id,sender_id:user.id,body:draft.trim()||"📎",attachment_path:path,attachment_name:file.name,attachment_type:file.type,attachment_size:file.size}).select("id,created_at").single();if(error){await supabase.storage.from("topgram-chat-media").remove([path]);throw error;}if(data){const item:Message={id:data.id,chatId:active.id,text:draft.trim(),mine:true,time:timeLabel(data.created_at),attachmentPath:path,attachmentName:file.name,attachmentType:file.type,attachmentSize:file.size};setMessages(prev=>prev.some(m=>m.id===item.id)?prev:[...prev,item]);setChats(prev=>prev.map(c=>c.id===active.id?{...c,preview:"📎 "+file.name,time:item.time}:c));setDraft("");}}catch(error){setActionError("Не удалось отправить файл: "+(error instanceof Error?error.message:"ошибка загрузки"));}finally{setUploadBusy(false);if(fileInputRef.current)fileInputRef.current.value="";}}
 async function openAttachment(path:string,download=false){if(!supabase)return;const {data,error}=await supabase.storage.from("topgram-chat-media").createSignedUrl(path,300,{download});if(error||!data?.signedUrl){setActionError("Не удалось открыть вложение.");return;}window.open(data.signedUrl,"_blank","noopener,noreferrer");}
 async function saveProfile(e:FormEvent){e.preventDefault();if(busy)return;if(!supabase||!user){setActionError("Сначала войди в аккаунт.");return;}const username=profileUsername.trim().replace(/^@/,"").toLowerCase();if(username&&!/^[a-zA-Z][a-zA-Z0-9_]{3,30}[a-zA-Z0-9]$/.test(username)){setActionError("Username должен содержать 5–32 символа: латинские буквы, цифры и _. Начинаться с буквы и не заканчиваться _.");return;}const fullName=[firstName.trim(),lastName.trim()].filter(Boolean).join(" ")||"Пользователь";setBusy(true);setActionError("");try{const {error}=await supabase.from("tg_profiles").update({username:username||null,display_name:fullName,first_name:firstName.trim(),last_name:lastName.trim(),birthday:birthday||null,bio:profileBio.trim(),updated_at:new Date().toISOString()}).eq("id",user.id);if(error)throw error;setProfileName(fullName);setProfileUsername(username);setSettingsOpen(false);setActionError("");if(usernameEditOpen){setUsernameEditOpen(false);setSettingsSection("account");}else{setSettingsSection("home");if(accountReturnToProfile)setMobileTab("profile");setAccountReturnToProfile(false);}}catch(error){const message=error instanceof Error?error.message:"Не удалось сохранить профиль.";setActionError(message.toLowerCase().includes("duplicate")||message.toLowerCase().includes("unique")?"Этот username уже занят.":message);}finally{setBusy(false);}}
 async function createConversation(e:FormEvent){e.preventDefault();if(!supabase||!user){setActionError("Аккаунт ещё создаётся. Попробуй снова через пару секунд.");return;}setBusy(true);setActionError("");try{let targetId:string|undefined;let title=newTitle.trim();let kind:Kind=modal==="direct"?"direct":modal==="channel"?"channel":"group";if(kind==="direct"){const username=newUsername.trim().replace(/^@/,"").toLowerCase();if(!username){setActionError("Введи username пользователя.");return;}const {data:profile,error}=await supabase.from("tg_profiles").select("id,username,display_name").eq("username",username).maybeSingle();if(error||!profile){setActionError("Пользователь не найден. Проверь username.");return;}if(profile.id===user.id){setActionError("Нельзя создать переписку с самим собой.");return;}targetId=profile.id;title="";const existing=chats.find(chat=>chat.kind==="direct"&&chat.peerId===targetId);if(existing){setModal(null);setNewUsername("");setActiveId(existing.id);setMobileTab("chats");setMobileChat(true);return;}}else if(!title){setActionError("Название обязательно — минимум 1 символ.");return;}if(kind==="channel"&&channelType==="public"&&!/^[a-zA-Z][a-zA-Z0-9_]{4,31}$/.test(channelUsername)){setActionError("Публичная ссылка: от 5 до 32 символов, латинские буквы, цифры и _.");return;}
 const inviteToken=kind==="channel"&&channelType==="private"?crypto.randomUUID().replace(/-/g,"").slice(0,24):null;
 const metadata={kind,title:title||null,created_by:user.id,...(kind==="group"?{avatar_url:groupPhoto||null,auto_delete_seconds:({"Выкл.":0,"1 день":86400,"1 неделя":604800,"1 месяц":2592000} as Record<string,number>)[groupAutoDelete]??0}:{}),...(kind==="channel"?{description:channelDescription.trim()||null,avatar_url:channelPhoto||null,public_username:channelType==="public"?channelUsername.trim().toLowerCase():null,invite_token:inviteToken}:{})};
 const {data:conversation,error:convError}=await supabase.from("tg_conversations").insert(metadata).select("id").single();if(convError||!conversation){setActionError(convError?.message??"Не удалось создать чат.");return;}
 const memberIds=kind==="group"?selectedGroupMembers:(targetId?[targetId]:[]);const rows=[{conversation_id:conversation.id,user_id:user.id,role:"owner"},...memberIds.map(memberId=>({conversation_id:conversation.id,user_id:memberId,role:"member"}))];
 const {error:memberError}=await supabase.from("tg_conversation_members").insert(rows);if(memberError){const cleanup=await supabase.from("tg_conversations").delete().eq("id",conversation.id);setActionError("Не удалось добавить участников: "+memberError.message+(cleanup.error?" (чат остался создан, удаление не удалось)":" (созданный чат удалён)"));return;}
 setModal(null);setNewTitle("");setNewUsername("");setSelectedGroupMembers([]);setContactSearch("");setGroupStep("members");setChannelStep("details");setChannelDescription("");setChannelUsername("");setGroupPhoto("");setChannelPhoto("");setGroupAutoDelete("Выкл.");await loadWorkspace(user);setActiveId(conversation.id);setMobileTab("chats");setMobileChat(true);if(kind==="channel"){const channelUrl=window.location.origin+window.location.pathname+(inviteToken?"?invite="+inviteToken:"?channel="+encodeURIComponent(channelUsername.trim().toLowerCase()));void navigator.clipboard?.writeText(channelUrl).catch(()=>{});setActionError("Ссылка на канал скопирована: "+channelUrl);}
 }finally{setBusy(false);}}
 if(!authReady)return <div className="loading"><LoaderCircle className="spin"/>Загружаем TopGram…</div>;
 if(!isSupabaseConfigured)return <main className="auth-screen"><div className="auth-card config-card"><div className="brand-mark">t</div><div className="eyebrow">TOPGRAM · ПОДКЛЮЧЕНИЕ</div><h1>Нужно подключить сервер</h1><p>Демо-режим отключён. Чтобы вход и переписки работали по-настоящему, добавь публичные настройки Supabase в GitHub Actions.</p><div className="config-steps"><b>В репозитории GitHub открой:</b><span>Settings → Secrets and variables → Actions</span><b>Добавь Secrets:</b><code>VITE_SUPABASE_URL</code><code>VITE_SUPABASE_ANON_KEY</code><small>Используй URL проекта и publishable/anon key из Supabase. Service role key сюда добавлять нельзя.</small></div></div></main>;
 if(!user)return <main className="auth-screen"><div className="auth-card"><div className="brand-mark">t</div><div className="eyebrow">TOPGRAM MESSENGER</div><h1>{codeSent?"Подтверди вход":"Войти в TopGram"}</h1><p>{codeSent?"Мы отправили одноразовый код в TopGram-бот. Введи его ниже.":"Сначала получи свой номер TopGram в официальном боте, затем запроси код для входа."}</p><div className="bot-connect"><a href="https://t.me/topgramnumbers_bot" target="_blank" rel="noreferrer">Открыть @topgramnumbers_bot ↗</a><span>Нажми Start, чтобы получить номер</span></div>{!codeSent?<form onSubmit={requestLoginCode}><label>Номер TopGram</label><input type="text" inputMode="tel" autoComplete="username" value={tgNumber} onChange={e=>setTgNumber(e.target.value)} placeholder="+7 123456" required/><button className="primary wide" disabled={authBusy}>{authBusy?"Отправляем…":"Получить код в TopGram"}</button></form>:<form onSubmit={verifyLoginCode}><label>Номер TopGram</label><input type="text" value={tgNumber} readOnly/><label>Код из TopGram</label><input type="text" inputMode="numeric" autoComplete="one-time-code" maxLength={6} value={loginCode} onChange={e=>setLoginCode(e.target.value.replace(/\D/g,"").slice(0,6))} placeholder="123456" required/><button className="primary wide" disabled={authBusy}>{authBusy?"Проверяем…":"Войти в TopGram"}</button><button type="button" className="text-button" disabled={authBusy} onClick={()=>{setCodeSent(false);setLoginCode("");setAuthError("");}}>Изменить номер</button></form>}{authError&&<div className="error">{authError}</div>}<div className="auth-footnote">Код приходит только в TopGram-бот и действует 5 минут. Никому его не пересылай.</div></div></main>;
 if(mfaLoginRequired)return <main className="auth-screen"><form className="auth-card" onSubmit={e=>{e.preventDefault();void verifyLoginMfa();}}><div className="brand-mark">t</div><div className="eyebrow">TOPGRAM SECURITY</div><h1>Подтверди вход</h1><p>Введи шестизначный код из приложения-аутентификатора.</p><input className="modal-input" inputMode="numeric" autoComplete="one-time-code" maxLength={6} value={mfaLoginCode} onChange={e=>setMfaLoginCode(e.target.value.replace(/\D/g,""))} placeholder="000000"/>{mfaLoginError&&<div className="error">{mfaLoginError}</div>}<button className="primary wide" disabled={mfaLoginBusy||mfaLoginCode.length!==6}>{mfaLoginBusy?"Проверяем…":"Подтвердить"}</button><button type="button" className="privacy-option" onClick={()=>void supabase?.auth.signOut()}>Выйти</button></form></main>;
